package be.winnetrie.mod.simpleserverutilities.jail;
import java.util.Map;import java.util.UUID;import java.util.concurrent.ConcurrentHashMap;import net.minecraft.core.BlockPos;import net.minecraft.core.component.DataComponents;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.Items;
/** Runtime two-corner selection state for the SSU Jail Setup Tool. */
public final class JailSetupToolManager{public static final String TOOL_NAME="SSU Jail Setup Tool";private final Map<UUID,Selection> selections=new ConcurrentHashMap<>();public void giveTool(ServerPlayer p){ItemStack s=new ItemStack(Items.IRON_BARS);s.set(DataComponents.ITEM_NAME,Component.literal(TOOL_NAME));if(!p.getInventory().add(s))p.drop(s,false);}public boolean isTool(ServerPlayer p,ItemStack s){return p!=null&&s!=null&&!s.isEmpty()&&s.is(Items.IRON_BARS)&&TOOL_NAME.equals(s.getHoverName().getString());}public Selection selection(ServerPlayer p){return selections.computeIfAbsent(p.getUUID(),x->new Selection());}public Selection existing(ServerPlayer p){return p==null?null:selections.get(p.getUUID());}public void forget(UUID id){if(id!=null)selections.remove(id);}public void clear(){selections.clear();}public static final class Selection{public String dimension="";public BlockPos point1,point2;public void setPoint1(String d,BlockPos p){String n=d==null?"":d;if(point2!=null&&!dimension.isBlank()&&!dimension.equals(n))point2=null;dimension=n;point1=p==null?null:p.immutable();}public void setPoint2(String d,BlockPos p){String n=d==null?"":d;if(point1!=null&&!dimension.isBlank()&&!dimension.equals(n))point1=null;dimension=n;point2=p==null?null:p.immutable();}public boolean complete(){return point1!=null&&point2!=null&&!dimension.isBlank();}public void clear(){dimension="";point1=null;point2=null;}}}
